typedef struct Entity Entity;
typedef struct { void (*update)(Entity *e, float dt); } PhysicsComponent;
struct Entity {
    float x, y;                          /* pan-domain state */
    PhysicsComponent *physics;           /* pluggable slots   */
    GraphicsComponent *graphics;
};
void entity_update(Entity *e, float dt) {
    if (e->physics)  e->physics->update(e, dt);
    if (e->graphics) e->graphics->update(e, dt);
}
